func timerStubInstanceOf(tb assert.TB, s *clocktest.TimerStub) timerStubInstance {
	tb.Helper()
	return timerStubInstance{
		Stub: s.OnC.MethodStub,
		Call: func() {
			_ = timerStubC(tb, s)
		},
	}
}

// TestTimerStub checks the methods, the constructors and the options of
// the double TimerStub.
func TestTimerStub(t *testing.T) {
	t.Parallel()

	t.Run("C", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "C", timerStubCSubject)
	})

	t.Run("Reset", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Reset", timerStubResetSubject)
	})

	t.Run("Stop", func(t *testing.T) {
		t.Parallel()
		stub.Behaviour(t, "Stop", timerStubStopSubject)
	})

	t.Run("ResetCalls", func(t *testing.T) {
		t.Parallel()

		t.Run("C", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "C", timerStubCSubject)
		})

		t.Run("Reset", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Reset", timerStubResetSubject)
		})

		t.Run("Stop", func(t *testing.T) {
			t.Parallel()
			stub.ResetBehaviour(t, "Stop", timerStubStopSubject)
		})
	})

	t.Run("TimerStubStrict", func(t *testing.T) {
		t.Parallel()
		stub.StrictBehaviour(t, func(tb assert.TB) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStub(tb, clocktest.TimerStubStrict()))
		})
	})

	t.Run("TimerStubDelegateTo", func(t *testing.T) {
		t.Parallel()

		t.Run("passes C to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := clocktest.NewTimerStub(t)
			s := clocktest.NewTimerStub(t, clocktest.TimerStubDelegateTo(inner))
			_ = timerStubC(t, s)
			inner.OnC.AssertCalledOnce(t, "C calls the implementation")
		})

		t.Run("passes Reset to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := clocktest.NewTimerStub(t)
			s := clocktest.NewTimerStub(t, clocktest.TimerStubDelegateTo(inner))
			_ = timerStubReset(t, s)
			inner.OnReset.AssertCalledOnce(t, "Reset calls the implementation")
		})

		t.Run("passes Stop to the implementation", func(t *testing.T) {
			t.Parallel()
			inner := clocktest.NewTimerStub(t)
			s := clocktest.NewTimerStub(t, clocktest.TimerStubDelegateTo(inner))
			_ = timerStubStop(t, s)
			inner.OnStop.AssertCalledOnce(t, "Stop calls the implementation")
		})
	})

	t.Run("TimerStubWithClock", func(t *testing.T) {
		t.Parallel()
		stub.ClockBehaviour(t, func(tb assert.TB, clk assert.Clock) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStub(tb, clocktest.TimerStubWithClock(clk)))
		})
	})

	t.Run("TimerStubWithRandSource", func(t *testing.T) {
		t.Parallel()
		stub.RandSourceBehaviour(t, func(tb assert.TB, src rand.Source) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStub(tb, clocktest.TimerStubWithRandSource(src)))
		})
	})

	t.Run("TimerStubBenchMode", func(t *testing.T) {
		t.Parallel()
		stub.BenchModeBehaviour(t, func(tb assert.TB) timerStubInstance {
			return timerStubInstanceOf(tb, clocktest.NewTimerStub(tb, clocktest.TimerStubBenchMode()))
		})
	})

	t.Run("TimerStubWithLatency", func(t *testing.T) {
		t.Parallel()
		stub.LatencyBehaviour(t, func(tb assert.TB, d time.Duration, clk assert.Clock) timerStubInstance {
			return timerStubInstanceOf(
				tb,
				clocktest.NewTimerStub(tb, clocktest.TimerStubWithClock(clk), clocktest.TimerStubWithLatency(d)),
			)
		})
	})

	t.Run("WithTimerC", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of C", func(t *testing.T) {
			t.Parallel()
			called := false
			s := clocktest.NewTimerStub(t, clocktest.WithTimerC(func() <-chan time.Time {
				called = true
				var z0 <-chan time.Time
				return z0
			}))
			_ = timerStubC(t, s)
			assert.True(t, called, "WithTimerC sets the function of C")
		})
	})

	t.Run("WithTimerReset", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Reset", func(t *testing.T) {
			t.Parallel()
			called := false
			s := clocktest.NewTimerStub(t, clocktest.WithTimerReset(func(_ time.Duration) bool {
				called = true
				var z0 bool
				return z0
			}))
			_ = timerStubReset(t, s)
			assert.True(t, called, "WithTimerReset sets the function of Reset")
		})
	})

	t.Run("WithTimerStop", func(t *testing.T) {
		t.Parallel()

		t.Run("sets the function of Stop", func(t *testing.T) {
			t.Parallel()
			called := false
			s := clocktest.NewTimerStub(t, clocktest.WithTimerStop(func() bool {
				called = true
				var z0 bool
				return z0
			}))
			_ = timerStubStop(t, s)
			assert.True(t, called, "WithTimerStop sets the function of Stop")
		})
	})
}

